cp "$PROC/Cards/run_card.dat" "$PROC/Cards/run_card.dat.before_minimizer_cards"
restore() {
  cp "$PROC/Cards/param_card.dat.before_minimizer_cards" "$PROC/Cards/param_card.dat"
  cp "$PROC/Cards/run_card.dat.before_minimizer_cards" "$PROC/Cards/run_card.dat"
}
