sed -E -i.bak "s/^ *[0-9]+ *= *nevents/ 10000 = nevents/" "$PROC/Cards/run_card.dat"
done_already() { ls "$PROC"/Events/"$1"_decayed_*/*delphes_events.root >/dev/null 2>&1; }

